choose.otherwise:
UPDATE pattern_steps ps JOIN financial_patterns fp USING (financial_pattern_id)
SET ps.voice_script_outdated = ps.voice_script_outdated OR
        (ps.voice_file_path IS NOT NULL AND BINARY ps.instruction_text != BINARY #{text}),
    ps.instruction_text = #{text}, ps.voice_mode = #{voiceMode}
WHERE fp.user_id = #{userId} AND fp.financial_pattern_id = #{patternId}
  AND fp.is_active = TRUE AND ps.step_code = #{target}

UPDATE pattern_steps ps JOIN financial_patterns fp USING (financial_pattern_id)
SET ps.voice_file_path = #{filePath}, ps.voice_content_type = #{contentType},
    ps.voice_script_outdated = FALSE
WHERE fp.user_id = #{userId} AND fp.financial_pattern_id = #{patternId}
  AND fp.is_active = TRUE AND ps.step_code = #{target}
